import React from 'react';
import '../Stepper.scss';
import clsx from 'clsx';
import StepContext from '../Step/StepContext';
import useWindowSize from '../../../hooks/useWindowSize';

const StepLabel: React.FC<React.HTMLProps<HTMLDivElement>> = ({
  children,
}) => {
  const { completed, active } = React.useContext(StepContext);
  const { isMobile } = useWindowSize();
  return (
    <div id="mpa-LabelContainer" className={clsx("mpa-step-label-container", { "step-label-container-mobile": isMobile })}>
      <span
        id="mpa-Label"
        className={clsx("mpa-step-label", {
          "step-label-mobile": isMobile,
          active: active,
          completed: completed,
        })}
      >
        {children}
      </span>
    </div>
  );
};

export default StepLabel;
